CREATE TABLE IF NOT EXISTS restaurants (id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,address VARCHAR(255) NOT NULL,is_open BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS menu_items (id SERIAL PRIMARY KEY,restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,name VARCHAR(120) NOT NULL,description TEXT,price NUMERIC(10,2) NOT NULL CHECK (price >= 0),available BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS orders (id SERIAL PRIMARY KEY,customer_name VARCHAR(120) NOT NULL,restaurant_id INTEGER NOT NULL REFERENCES restaurants(id),total_amount NUMERIC(10,2) NOT NULL CHECK (total_amount >= 0),status VARCHAR(30) NOT NULL DEFAULT 'PLACED',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id SERIAL PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,menu_item_id INTEGER NOT NULL REFERENCES menu_items(id),quantity INTEGER NOT NULL CHECK (quantity > 0),unit_price NUMERIC(10,2) NOT NULL CHECK (unit_price >= 0));
INSERT INTO restaurants(name,address) VALUES ('Spice Hub','MG Road'),('Burger Garage','Station Road') ON CONFLICT DO NOTHING;
INSERT INTO menu_items(restaurant_id,name,description,price) SELECT id,'Paneer Wrap','Grilled paneer wrap',149 FROM restaurants WHERE name='Spice Hub' AND NOT EXISTS (SELECT 1 FROM menu_items WHERE name='Paneer Wrap');
INSERT INTO menu_items(restaurant_id,name,description,price) SELECT id,'Masala Fries','Crispy spiced fries',99 FROM restaurants WHERE name='Spice Hub' AND NOT EXISTS (SELECT 1 FROM menu_items WHERE name='Masala Fries');
INSERT INTO menu_items(restaurant_id,name,description,price) SELECT id,'Classic Burger','Vegetarian burger',179 FROM restaurants WHERE name='Burger Garage' AND NOT EXISTS (SELECT 1 FROM menu_items WHERE name='Classic Burger');
